create table if not exists public."ProductSecondaryCategory" ("productId" text not null references public."Product"(id) on delete cascade,"categoryId" text not null references public."Category"(id) on delete cascade,"createdAt" timestamp(3) not null default now(),primary key ("productId","categoryId"));
create index if not exists "ProductSecondaryCategory_categoryId_idx" on public."ProductSecondaryCategory"("categoryId","productId");
alter table public."ProductSecondaryCategory" enable row level security;
drop policy if exists "public_read_secondary_categories" on public."ProductSecondaryCategory";
create policy "public_read_secondary_categories" on public."ProductSecondaryCategory" for select to anon, authenticated using (exists(select 1 from public."Product" p join public."Category" c on c.id="ProductSecondaryCategory"."categoryId" where p.id="ProductSecondaryCategory"."productId" and p."isPublished"=true and c."isPublished"=true));
do $$ begin if not exists(select 1 from pg_type where typname='TaxonomyDimension') then create type public."TaxonomyDimension" as enum ('REGULATORY_CLASSIFICATION','MEDICAL_SPECIALTY','CLINICAL_APPLICATION','INTENDED_USE','CARE_SETTING','PRODUCT_TYPE','PRODUCT_TECHNOLOGY','COLLECTION','COMPATIBILITY'); end if; end $$;
create table if not exists public."TaxonomyTerm" (id text primary key default gen_random_uuid()::text,dimension public."TaxonomyDimension" not null,slug text not null,"nameFa" text not null default '',"nameTr" text not null default '',"nameEn" text not null default '',"nameAr" text not null default '',"descriptionFa" text not null default '',"descriptionTr" text not null default '',"descriptionEn" text not null default '',"descriptionAr" text not null default '',"sortOrder" integer not null default 0,"isPublished" boolean not null default true,"createdAt" timestamp(3) not null default now(),"updatedAt" timestamp(3) not null default now(),unique(dimension,slug));
create index if not exists "TaxonomyTerm_dimension_sort_idx" on public."TaxonomyTerm"(dimension,"sortOrder",slug);
alter table public."TaxonomyTerm" enable row level security;
drop policy if exists "public_read_published_taxonomy_terms" on public."TaxonomyTerm";
create policy "public_read_published_taxonomy_terms" on public."TaxonomyTerm" for select to anon, authenticated using ("isPublished"=true);
create table if not exists public."ProductTaxonomy" ("productId" text not null references public."Product"(id) on delete cascade,"termId" text not null references public."TaxonomyTerm"(id) on delete cascade,"createdAt" timestamp(3) not null default now(),primary key ("productId","termId"));
create index if not exists "ProductTaxonomy_termId_idx" on public."ProductTaxonomy"("termId","productId");
alter table public."ProductTaxonomy" enable row level security;
drop policy if exists "public_read_product_taxonomy" on public."ProductTaxonomy";
create policy "public_read_product_taxonomy" on public."ProductTaxonomy" for select to anon, authenticated using (exists(select 1 from public."Product" p join public."TaxonomyTerm" t on t.id="ProductTaxonomy"."termId" where p.id="ProductTaxonomy"."productId" and p."isPublished"=true and t."isPublished"=true));
create or replace function public.admin_catalog_taxonomy_bundle(p_token text,p_search text default '',p_dimension text default '') returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_q text:=lower(trim(coalesce(p_search,''))); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return jsonb_build_object('terms',(select coalesce(jsonb_agg(to_jsonb(x) order by x.dimension,x."sortOrder",x.slug),'[]'::jsonb) from (select t.id,t.dimension::text as dimension,t.slug,t."nameFa",t."nameTr",t."nameEn",t."nameAr",t."descriptionFa",t."descriptionTr",t."descriptionEn",t."descriptionAr",t."sortOrder",t."isPublished",count(pt."productId")::int as "productCount" from public."TaxonomyTerm" t left join public."ProductTaxonomy" pt on pt."termId"=t.id where (coalesce(p_dimension,'')='' or t.dimension::text=p_dimension) and (v_q='' or lower(t.slug) like '%'||v_q||'%' or lower(t."nameFa") like '%'||v_q||'%' or lower(t."nameTr") like '%'||v_q||'%' or lower(t."nameEn") like '%'||v_q||'%' or lower(t."nameAr") like '%'||v_q||'%') group by t.id) x),'dimensions',jsonb_build_array('REGULATORY_CLASSIFICATION','MEDICAL_SPECIALTY','CLINICAL_APPLICATION','INTENDED_USE','CARE_SETTING','PRODUCT_TYPE','PRODUCT_TECHNOLOGY','COLLECTION','COMPATIBILITY')); end $$;
create or replace function public.admin_upsert_taxonomy_term(p_token text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_id text:=nullif(trim(coalesce(p_data->>'id','')),''); v_dim public."TaxonomyDimension"; v_slug text:=lower(trim(coalesce(p_data->>'slug',''))); v_en text:=trim(coalesce(p_data->>'nameEn','')); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; begin v_dim:=(p_data->>'dimension')::public."TaxonomyDimension"; exception when others then raise exception 'invalid taxonomy dimension'; end; if v_slug='' then v_slug:=lower(regexp_replace(v_en,'[^a-zA-Z0-9]+','-','g')); end if; v_slug:=trim(both '-' from v_slug); if v_slug='' or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'invalid taxonomy slug'; end if; if trim(coalesce(p_data->>'nameFa',''))='' or v_en='' then raise exception 'taxonomy Persian and English names required'; end if; if exists(select 1 from public."TaxonomyTerm" where dimension=v_dim and slug=v_slug and (v_id is null or id<>v_id)) then raise exception 'taxonomy term already exists'; end if; if v_id is null then v_id:=gen_random_uuid()::text; insert into public."TaxonomyTerm"(id,dimension,slug,"nameFa","nameTr","nameEn","nameAr","descriptionFa","descriptionTr","descriptionEn","descriptionAr","sortOrder","isPublished","createdAt","updatedAt") values(v_id,v_dim,v_slug,trim(coalesce(p_data->>'nameFa','')),trim(coalesce(p_data->>'nameTr','')),v_en,trim(coalesce(p_data->>'nameAr','')),coalesce(p_data->>'descriptionFa',''),coalesce(p_data->>'descriptionTr',''),coalesce(p_data->>'descriptionEn',''),coalesce(p_data->>'descriptionAr',''),coalesce(nullif(p_data->>'sortOrder','')::int,0),coalesce((p_data->>'isPublished')::boolean,true),now(),now()); else update public."TaxonomyTerm" set dimension=v_dim,slug=v_slug,"nameFa"=trim(coalesce(p_data->>'nameFa','')),"nameTr"=trim(coalesce(p_data->>'nameTr','')),"nameEn"=v_en,"nameAr"=trim(coalesce(p_data->>'nameAr','')),"descriptionFa"=coalesce(p_data->>'descriptionFa',''),"descriptionTr"=coalesce(p_data->>'descriptionTr',''),"descriptionEn"=coalesce(p_data->>'descriptionEn',''),"descriptionAr"=coalesce(p_data->>'descriptionAr',''),"sortOrder"=coalesce(nullif(p_data->>'sortOrder','')::int,0),"isPublished"=coalesce((p_data->>'isPublished')::boolean,true),"updatedAt"=now() where id=v_id; if not found then raise exception 'taxonomy term not found'; end if; end if; return jsonb_build_object('id',v_id,'dimension',v_dim::text,'slug',v_slug); end $$;
create or replace function public.admin_archive_taxonomy_term(p_token text,p_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; update public."TaxonomyTerm" set "isPublished"=false,"updatedAt"=now() where id=p_id; return found; end $$;
create or replace function public.admin_set_product_catalog_links(p_token text,p_product_id text,p_brand_id text default null,p_secondary_categories jsonb default '[]'::jsonb,p_term_ids jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_brand_name text:=''; v_primary text; v_value jsonb; v_id text; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; select "categoryId" into v_primary from public."Product" where id=p_product_id; if not found then raise exception 'product not found'; end if; if nullif(trim(coalesce(p_brand_id,'')),'') is not null then select name into v_brand_name from public."Brand" where id=p_brand_id and "isPublished"=true; if not found then raise exception 'invalid brand'; end if; end if; update public."Product" set "brandId"=nullif(trim(coalesce(p_brand_id,'')),''),brand=coalesce(v_brand_name,''),"updatedAt"=now() where id=p_product_id; delete from public."ProductSecondaryCategory" where "productId"=p_product_id; if p_secondary_categories is not null and jsonb_typeof(p_secondary_categories)='array' then for v_value in select value from jsonb_array_elements(p_secondary_categories) loop v_id=trim(v_value#>>'{}'); if v_id<>'' and v_id<>v_primary and exists(select 1 from public."Category" where id=v_id and "isPublished"=true) then insert into public."ProductSecondaryCategory"("productId","categoryId") values(p_product_id,v_id) on conflict do nothing; end if; end loop; end if; delete from public."ProductTaxonomy" where "productId"=p_product_id; if p_term_ids is not null and jsonb_typeof(p_term_ids)='array' then for v_value in select value from jsonb_array_elements(p_term_ids) loop v_id=trim(v_value#>>'{}'); if v_id<>'' and exists(select 1 from public."TaxonomyTerm" where id=v_id and "isPublished"=true) then insert into public."ProductTaxonomy"("productId","termId") values(p_product_id,v_id) on conflict do nothing; end if; end loop; end if; return jsonb_build_object('productId',p_product_id,'brandId',nullif(trim(coalesce(p_brand_id,'')),''),'secondaryCount',(select count(*) from public."ProductSecondaryCategory" where "productId"=p_product_id),'taxonomyCount',(select count(*) from public."ProductTaxonomy" where "productId"=p_product_id)); end $$;
create or replace function public.admin_product_catalog_links(p_token text,p_product_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return jsonb_build_object('brandId',(select "brandId" from public."Product" where id=p_product_id),'secondaryCategoryIds',(select coalesce(jsonb_agg("categoryId"),'[]'::jsonb) from public."ProductSecondaryCategory" where "productId"=p_product_id),'termIds',(select coalesce(jsonb_agg("termId"),'[]'::jsonb) from public."ProductTaxonomy" where "productId"=p_product_id)); end $$;
revoke all on function public.admin_catalog_taxonomy_bundle(text,text,text) from public,anon,authenticated; revoke all on function public.admin_upsert_taxonomy_term(text,jsonb) from public,anon,authenticated; revoke all on function public.admin_archive_taxonomy_term(text,text) from public,anon,authenticated; revoke all on function public.admin_set_product_catalog_links(text,text,text,jsonb,jsonb) from public,anon,authenticated; revoke all on function public.admin_product_catalog_links(text,text) from public,anon,authenticated;
grant execute on function public.admin_catalog_taxonomy_bundle(text,text,text) to service_role; grant execute on function public.admin_upsert_taxonomy_term(text,jsonb) to service_role; grant execute on function public.admin_archive_taxonomy_term(text,text) to service_role; grant execute on function public.admin_set_product_catalog_links(text,text,text,jsonb,jsonb) to service_role; grant execute on function public.admin_product_catalog_links(text,text) to service_role;
grant select on public."ProductSecondaryCategory",public."TaxonomyTerm",public."ProductTaxonomy" to anon,authenticated,service_role;
